import { writeFile } from "node:fs/promises";
import { loadAuthoringCatalog } from "./practice-content.mjs";
import { JUDGE_VERSION } from "./judge-content.mjs";
const quote = (value) => `'${value.replaceAll("'", "''")}'`;
const json = (value) => `${quote(JSON.stringify(value))}::jsonb`;
const questions = await loadAuthoringCatalog();
const sql = [
  "-- Generated by scripts/generate-question-copy.mjs. Text and hints only; no grading or fixture changes.",
  "begin;",
  ...questions.map(
    (q) =>
      `update game_private.question_help set title = ${quote(q.title)}, description = ${quote(q.description)}, hints = ${json(q.hints)} where ruin_id = ${q.id} and dataset_version = ${quote(JUDGE_VERSION)};`,
  ),
  "commit;",
  "",
].join("\n");
await writeFile(
  new URL(
    "../supabase/migrations/20260904180000_plain_language_question_copy.sql",
    import.meta.url,
  ),
  sql,
);
console.log(
  "Generated forward-only question copy update; no database contacted.",
);
